description:
Wrap an object in a `Proxy` that records every change and refuses wrong types.

```
const user = tracked({ name: "Ada", age: 36 });
user.age = 37;
user.name = 42        // throws TypeError: name must be a string
delete user.age;
changes(user)         // ["set age: 36 -> 37", "delete age"]
```

starter.main.js:
const logs = new WeakMap();

function tracked(target) {
  const log = [];
  const proxy = new Proxy(target, {
    // TODO: set and deleteProperty
  });
  logs.set(proxy, log);
  return proxy;
}

function changes(proxy) {
  return logs.get(proxy) || [];
}
